def solution(S: str) -> str:
    n = len(S)
    layers = []              # layers[i]: {(prev, cur): previous state}
    cur = {('#', '#'): None}  # '#' = nothing yet
    for ch in S:
        opts = 'ab' if ch in '?-' else ch
        nxt = {}
        for (x, y) in cur:
            for c in opts:
                if x == y == c:
                    continue
                nxt.setdefault((y, c), (x, y))
        if not nxt:
            return ""
        layers.append(nxt)
        cur = nxt
    state = next(iter(cur))
    out = []
    for i in range(n - 1, -1, -1):
        out.append(state[1])
        state = layers[i][state]
    return "".join(reversed(out))
